 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find repeated non-background runs on the top/bottom edges.
    launchers = []
    launcher_colors = set()
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = g[r][c]
            end = c + 1
            while end < w and g[r][end] == color:
                end += 1
            if color != bg and end - c >= 2:
                launchers.append((r, c, end, color))
                launcher_colors.add(color)
            c = end

    # The scattered color is projected along the launcher's columns; impacts
    # (pre-existing scattered marks) become color 4.
    ray_colors = [v for v in counts if v != bg and v not in launcher_colors]
    ray = ray_colors[0]
    for r, c0, c1, _ in launchers:
        step = 1 if r == 0 else -1
        rr = r + step
        while 0 <= rr < h:
            for c in range(c0, c1):
                g[rr][c] = 4 if g[rr][c] == ray else ray
            rr += step
    return g
"
}

