    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    # Find contiguous non-background runs along each of the four borders.
    horizontal = []  # (edge row, start col, end col, color)
    for r in (0, h - 1):
        c = 0
        while c < w:
            e = c + 1
            while e < w and g[r][e] == g[r][c]:
                e += 1
            if g[r][c] != bg and e - c >= 2:
                horizontal.append((r, c, e, g[r][c]))
            c = e
    vertical = []  # (edge col, start row, end row, color)
    for c in (0, w - 1):
        r = 0
        while r < h:
            e = r + 1
            while e < h and g[e][c] == g[r][c]:
                e += 1
            if g[r][c] != bg and e - r >= 2:
                vertical.append((c, r, e, g[r][c]))
            r = e

    # Pair bars on opposite borders. A scattered mark at a bar's offset
    # activates that same offset on both paired bars.
    pairs = []
    for a in horizontal:
        for b in horizontal:
            if a[0] == 0 and b[0] == h - 1 and a[3] == b[3] and a[2]-a[1] == b[2]-b[1]:
                pairs.append(('h', a, b))
    for a in vertical:
        for b in vertical:
            if a[0] == 0 and b[0] == w - 1 and a[3] == b[3] and a[2]-a[1] == b[2]-b[1]:
                pairs.append(('v', a, b))
    if not pairs:
        return g

    bar_colors = {p[1][3] for p in pairs}
    ray_colors = [x for x in counts if x != bg and x not in bar_colors]
    if not ray_colors:
        return g
    ray = ray_colors[0]
    original = [row[:] for row in g]

    for axis, first, second in pairs:
        if axis == 'h':
            # Each bar's varying coordinate is column; determine activated offsets.
            starts = [first[1], second[1]]
            length = first[2] - first[1]
            active = set()
            for r in range(h):
                for c in range(w):
                    if original[r][c] == ray:
                        for start in starts:
                            off = c - start
                            if 0 <= off < length:
                                active.add(off)
            for edge, start, end, _ in (first, second):
                step = 1 if edge == 0 else -1
                for off in active:
                    c = start + off
                    rr = edge + step
                    while 0 <= rr < h:
                        if original[rr][c] == ray:
                            g[rr][c] = 4
                            break
                        g[rr][c] = ray
                        rr += step
        else:
            starts = [first[1], second[1]]
            length = first[2] - first[1]
            active = set()
            for r in range(h):
                for c in range(w):
                    if original[r][c] == ray:
                        for start in starts:
                            off = r - start
                            if 0 <= off < length:
                                active.add(off)
            for edge, start, end, _ in (first, second):
                step = 1 if edge == 0 else -1
                for off in active:
                    r = start + off
